function notify(message){clearTimeout(toastTimeout);$('#toast span').textContent=message;const toast=$('#toast');if($('#copy-dialog').matches(':popover-open'))$('#copy-dialog').append(toast);else if($('#preview-dialog').open)$('#preview-dialog').append(toast);else document.body.append(toast);toast.hidden=false;refreshIcons();toastTimeout=setTimeout(()=>toast.hidden=true,2400)}
const copyTimers=new WeakMap();
function copyFeedback(button){if(!button)return;clearTimeout(copyTimers.get(button));if(!button.dataset.originalMarkup)button.dataset.originalMarkup=button.innerHTML;button.classList.add('copy-success');button.innerHTML=svg('check');refreshIcons();if(!reduced())button.querySelector('svg')?.animate([{opacity:0,transform:'scale(.45) rotate(-25deg)'},{opacity:1,transform:'scale(1.15) rotate(0)'},{opacity:1,transform:'scale(1)'}],{duration:260,easing:'cubic-bezier(.2,.8,.2,1)'});copyTimers.set(button,setTimeout(()=>{button.innerHTML=button.dataset.originalMarkup;button.classList.remove('copy-success');delete button.dataset.originalMarkup;refreshIcons()},1000))}
async function copyText(text,button){try{await navigator.clipboard.writeText(text);copyFeedback(button);return true}catch{return false}}

function applyTranslations(scope=document){scope.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));scope.querySelectorAll('[data-i18n-label]').forEach(el=>{el.setAttribute('aria-label',t(el.dataset.i18nLabel));el.dataset.tip=t(el.dataset.i18nLabel)});scope.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder);el.setAttribute('aria-label',t(el.dataset.i18nPlaceholder))})}
function setTheme(value){state.theme=value;document.documentElement.style.colorScheme=value==='system'?'light dark':value;save()}
function expandCurrent(){const parts=state.path.split('/').filter(Boolean);for(let i=1;i<parts.length;i++)state.expanded.add(parts.slice(0,i).join('/')+'/')}
function renderTree(){
const root=`<div class="tree-item" ${state.path===''?'aria-current="page"':''} style="--depth:0"><span class="tree-disclose"></span><button class="tree-name" data-nav="">${svg('files')}<span>${t('allFiles')}</span></button></div>`;
const branch=(parent,depth)=>sorted((children.get(parent)||[]).filter(f=>f.dir)).map(f=>{const hasChildren=(children.get(f.path)||[]).some(c=>c.dir),expanded=state.expanded.has(f.path);return `<div class="tree-item" ${state.path===f.path?'aria-current="page"':''} style="--depth:${depth}"><button class="tree-disclose" data-expand="${esc(f.path)}" ${!hasChildren?'disabled':''} aria-expanded="${expanded}" aria-label="${t(expanded?'collapse':'expand')} ${esc(f.name)}">${svg('chevron-right')}</button><button class="tree-name" data-nav="${esc(f.path)}" data-tip="${esc(f.name)}"><img src="${icon(f)}" alt=""><span>${esc(f.name)}</span></button></div>${hasChildren?`<div class="tree-children" ${expanded?'':'hidden'}><div class="tree-children-inner">${branch(f.path,depth+1)}</div></div>`:''}`}).join('');
$('#tree').innerHTML=root+branch('',0);$('#tree').querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#tree').querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>toggleTree(b,b.getAttribute('aria-expanded')!=='true'));refreshIcons()}
const treeAnimations=new WeakMap();
function toggleTree(button,open){const panel=button.closest('.tree-item').nextElementSibling;if(!panel?.classList.contains('tree-children'))return;const from=panel.hidden?0:panel.getBoundingClientRect().height;treeAnimations.get(panel)?.cancel();button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',t(open?'collapse':'expand')+' '+button.dataset.expand.split('/').filter(Boolean).at(-1));if(open)state.expanded.add(button.dataset.expand);else state.expanded.delete(button.dataset.expand);panel.hidden=false;panel.style.height='auto';const target=open?panel.scrollHeight:0;if(reduced()){panel.hidden=!open;return}const animation=panel.animate([{height:from+'px',opacity:from===0?0:1},{height:target+'px',opacity:open?1:0}],{duration:250,easing:'cubic-bezier(.25,.8,.25,1)',fill:'both'});treeAnimations.set(panel,animation);animation.finished.then(()=>{panel.hidden=!open;animation.cancel();treeAnimations.delete(panel)}).catch(()=>{})}
let navigationVersion=0;
async function navigate(path){if((!byPath.get(path)?.dir&&path!=='')||path===state.path)return;const version=++navigationVersion,main=$('main'),old=state.path,up=old.startsWith(path)&&old!==path,direction=up?-1:1;hideTooltip();if(!reduced()){main.style.pointerEvents='none';await main.animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:`translateX(${-direction*22}px)`}],{duration:120,easing:'ease-in',fill:'forwards'}).finished.catch(()=>{})}if(version!==navigationVersion)return;
state.path=path;state.query='';state.limit=100;state.loading=false;$('#query').value='';expandCurrent();$('.layout').classList.remove('nav-open');$('#nav-toggle').setAttribute('aria-expanded','false');const route='/'+path.split('/').map(encodeURIComponent).join('/');if(location.pathname!==route)history.pushState(null,'',route);renderPage();main.getAnimations().forEach(a=>a.cancel());window.scrollTo({top:0,behavior:'instant'});if(!reduced())main.animate([{opacity:0,transform:`translateX(${direction*26}px)`},{opacity:1,transform:'translateX(0)'}],{duration:260,easing:'cubic-bezier(.2,.8,.2,1)'});main.style.pointerEvents='';}

window.addEventListener('popstate',()=>navigate(decodeURIComponent(location.pathname.slice(1))));
function renderPage(){document.documentElement.lang=state.lang;document.title='MoeCDN';applyTranslations();renderPickers();renderTree();renderHeading();renderList();refreshIcons()}
function renderHeading(){const parts=state.path.split('/').filter(Boolean);$('#title').textContent=parts.at(-1)||t('allFiles');$('#subtitle').textContent=t(state.path.includes('jquery')?'jquery':state.path==='lib/'?'libraries':state.path.includes('/font')?'fonts':'publicResources');$('#heading-icon').src=icons.folder;
$('#breadcrumbs').innerHTML=`<button data-nav="" aria-label="${t('root')}" data-tip="${t('root')}">${svg('house')}</button>`+parts.map((p,i)=>`${svg('chevron-right')}<button data-nav="${esc(parts.slice(0,i+1).join('/')+'/')}">${esc(p)}</button>`).join('');$('#breadcrumbs').querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));}
function renderList(){const query=state.query.trim().toLocaleLowerCase();let rows=sorted(query?files.filter(f=>(state.scope==='global'||(f.path.startsWith(state.path)&&f.path!==state.path))&&f.path.toLocaleLowerCase().includes(query)):(children.get(state.path)||[]));const count=rows.length;
$('#clear-search').hidden=!state.query;$('#empty').hidden=!!count;$('.file-table').hidden=!count;$('#search-global').hidden=state.scope==='global'||!query;$('#empty h2').textContent=t(query?'noResults':'emptyDirectory');$('#empty p').textContent=t(query?'noResultsHint':'emptyDirectoryHint');const folders=rows.filter(f=>f.dir).length,fileCount=count-folders,summary=[];if(query&&count)summary.push(t('resultCount',count),t(state.scope==='global'?'global':'current'));else{if(folders)summary.push(t('folderCount',folders));if(fileCount)summary.push(t('fileCount',fileCount))}if(fileCount)summary.push(size(rows.reduce((n,f)=>n+(f.size||0),0)));$('#result-count').textContent=summary.join(' · ');$('#result-count').hidden=!count;state.resultCount=count;$('#load-status').hidden=!state.loading;$('#load-status').textContent=t('loadingMore');$('#load-sentinel').hidden=count<=state.limit;
$('#rows').innerHTML=rows.slice(0,state.limit).map(f=>`<tr ${state.preview?.path===f.path?'data-selected="true"':''}><td><button class="file-open" data-file="${esc(f.path)}" aria-label="${t(f.dir?'openFolder':'previewFile')} ${esc(f.name)}" data-tip="${esc(f.name)}"><img src="${icon(f)}" alt=""><span class="file-label"><span class="file-name">${esc(f.name)}</span>${query?`<span class="file-path">/${esc(f.parent)}</span>`:''}</span></button></td><td class="size-column">${size(f.size)}</td><td class="date-column">${f.date}</td><td class="action-column"><div class="row-actions">${!f.dir?`<button class="icon-button row-copy" data-copy="${esc(f.path)}" aria-label="${t('copyLink')} ${esc(f.name)}" data-tip="${t('copyLink')}">${svg('copy')}</button><button class="icon-button" data-advanced="${esc(f.path)}" aria-label="${t('advancedCopy')} ${esc(f.name)}" data-tip="${t('advancedCopy')}">${svg('code-xml')}</button>`:`<button class="icon-button" data-copy="${esc(f.path)}" aria-label="${t('copyDirectory')}" data-tip="${t('copyDirectory')}">${svg('link')}</button>`}</div></td></tr>`).join('');
$('#rows').querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{const f=byPath.get(b.dataset.file);f.dir?navigate(f.path):openPreview(f,b)});$('#rows').querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const f=byPath.get(b.dataset.copy);if(!await copyText(originalUrl(f),b)){if(f.dir){notify(t('copyFailed'))}else {openCopy(f,b);setFormat('url');$('#copy-output').focus();$('#copy-output').select();notify(t('manualCopy'))}}});$('#rows').querySelectorAll('[data-advanced]').forEach(b=>b.onclick=()=>openCopy(byPath.get(b.dataset.advanced),b));refreshIcons()}
const pickerDefinitions={
theme:{options:[['system','monitor'],['light','sun'],['dark','moon']],selected:()=>state.theme,select:value=>{setTheme(value);renderPickers()}},
language:{options:[['zh-CN','languages','简体中文'],['en','languages','English']],selected:()=>state.lang,select:value=>{state.lang=value;save();renderPage()}},
scope:{options:[['current','folder-search'],['global','globe']],selected:()=>state.scope,select:value=>{state.scope=value;state.limit=100;renderPickers();renderList()}},
sort:{options:[['name','arrow-down-a-z','nameAsc'],['name-desc','arrow-up-a-z','nameDesc'],['date','calendar-days','dateDesc'],['size','arrow-down-wide-narrow','sizeDesc']],selected:()=>state.sort,select:value=>{state.sort=value;renderPickers();renderList()}}
};
const menuAnimations=new WeakMap();
function closeMenu(menu){if(menu.hidden||menu.dataset.closing==='true')return;menuAnimations.get(menu)?.cancel();menu.parentElement.querySelector('.menu-trigger').setAttribute('aria-expanded','false');menu.dataset.closing='true';if(reduced()){menu.hidden=true;delete menu.dataset.closing;return}const animation=menu.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(-5px) scale(.97)'}],{duration:140,easing:'ease-in',fill:'forwards'});menuAnimations.set(menu,animation);animation.finished.then(()=>{menu.hidden=true;delete menu.dataset.closing;animation.cancel();menuAnimations.delete(menu)}).catch(()=>{})}
function closeMenus(except){for(const menu of $$('.menu'))if(menu!==except)closeMenu(menu)}
function openMenu(menu){menuAnimations.get(menu)?.cancel();delete menu.dataset.closing;menu.hidden=false;menu.parentElement.querySelector('.menu-trigger').setAttribute('aria-expanded','true');if(!reduced()){const animation=menu.animate([{opacity:0,transform:'translateY(-5px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:180,easing:'cubic-bezier(.2,.8,.2,1)'});menuAnimations.set(menu,animation)}}

function renderPickers(){for(const [name,config] of Object.entries(pickerDefinitions)){const container=$('#'+name+'-picker'),selected=config.selected();const menu=container.querySelector('.menu');menu.innerHTML=config.options.map(([value,ic,label])=>`<button role="menuitemradio" data-option="${value}" aria-checked="${value===selected}">${svg(ic)}<span>${name==='language'?label:t(label||value)}</span>${value===selected?svg('check').replace('data-lucide','class="menu-check" data-lucide'):''}</button>`).join('')+(config.note?`<div class="menu-note">${t(config.note)}</div>`:'');const trigger=container.querySelector('.menu-trigger');if(name==='theme')trigger.innerHTML=svg(config.options.find(o=>o[0]===selected)[1]);if(name==='language')trigger.innerHTML=`<span class="language-glyph" aria-hidden="true">${state.lang==='zh-CN'?'中':'EN'}</span>`;const value=container.querySelector('.picker-value');if(value){const opt=config.options.find(o=>o[0]===selected);value.textContent=t(opt[2]||selected)}menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{closeMenus();config.select(b.dataset.option);trigger.focus()});}refreshIcons()}
for(const d of $$('.dropdown')){const trigger=d.querySelector('.menu-trigger'),menu=d.querySelector('.menu');trigger.onclick=()=>{const open=menu.hidden||menu.dataset.closing==='true';if(open){closeMenus(menu);openMenu(menu)}else closeMenu(menu);hideTooltip()};trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();closeMenus(menu);openMenu(menu);const options=[...menu.querySelectorAll('button')];options[e.key==='ArrowDown'?0:options.length-1].focus()}};menu.onkeydown=e=>{const options=[...menu.querySelectorAll('button')],i=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();options[e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length].focus()}}}
document.addEventListener('click',e=>{if(!e.target.closest('.dropdown'))closeMenus()});
